contracts/CouponDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

interface ISovereignBond {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title CouponDistributor
 * @dev "Push" model for yield distribution.
 *      - Admin deposits USDT.
 *      - Contract calculates share per token.
 *      - Users claim or Admin pushes.
 */
contract CouponDistributor is AccessControl {
    using SafeERC20 for IERC20;

    IERC20 public paymentToken; // USDT
    ISovereignBond public bond; // GBOND

    event CouponDistributed(uint256 totalAmount, uint256 ratePerShare);
    event CouponClaimed(address indexed user, uint256 amount);

    constructor(address _paymentToken, address _bond, address admin) {
        paymentToken = IERC20(_paymentToken);
        bond = ISovereignBond(_bond);
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
    }

    /**
     * @notice Distribute yield to all holders (Simplified).
     * @dev In production, iterating all holders is Gas Prohibitive.
     *      We usually use "Pull" (Merkle Drop) or "Checkpoints".
     *      For this Prototype/DPI Demo: We will assume a small set of holders
     *      OR Implement a simple Pull mechanism.
     *      Let's implement PULL for scalability.
     */

    // Total Yield Per Token (Accumulated)
    uint256 public cumulativeYieldPerToken;

    // User's paid checkpoint
    mapping(address => uint256) public userPaidPerToken;
    // Unclaimed rewards buffer
    mapping(address => uint256) public rewards;

    modifier updateReward(address account) {
        if (account != address(0)) {
            uint256 earned = (bond.balanceOf(account) *
                (cumulativeYieldPerToken - userPaidPerToken[account])) / 1e18;
            rewards[account] += earned;
            userPaidPerToken[account] = cumulativeYieldPerToken;
        }
        _;
    }

    /**
     * @notice Hook called by SovereignBond on Transfer/Mint/Burn.
     * @dev Updates rewards for both parties BEFORE their balance changes.
     */
    function onTokenTransfer(address from, address to) external {
        require(msg.sender == address(bond), "Only Bond");
        _updateRewardLocal(from);
        _updateRewardLocal(to);
    }

    function _updateRewardLocal(address account) internal {
        if (account != address(0)) {
            uint256 earned = (bond.balanceOf(account) *
                (cumulativeYieldPerToken - userPaidPerToken[account])) / 1e18;
            rewards[account] += earned;
            userPaidPerToken[account] = cumulativeYieldPerToken;
        }
    }

    // Reserve Logic
    uint256 public reserve;

    event ReserveFunded(uint256 amount);
    event YieldDistributed(uint256 rate, uint256 totalCost);

    /**
     * @notice Admin funds the contract reserve without distributing immediately.
     */
    function fundReserve(uint256 amount) external {
        paymentToken.safeTransferFrom(msg.sender, address(this), amount);
        reserve += amount;
        emit ReserveFunded(amount);
    }

    /**
     * @notice Distribute a specific Rate (e.g. 0.08 USDT per Bond).
     * @param ratePerToken Amount of Yield per 1 Bond (18 decimals).
     */
    function distribute(
        uint256 ratePerToken
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 supply = bond.totalSupply();
        require(supply > 0, "No bonds minted");

        uint256 totalCost = (supply * ratePerToken) / 1e18; // supply is 18 dec, rate is 18 dec. result should be 18 dec?
        // Wait. Supply 100 * 1e18. Rate 0.08 * 1e18.
        // Cost = (100e18 * 0.08e18) / 1e18 = 8e18. Correct.

        // Wait, supply is 18 decimals? Yes, Bond is ERC20.
        // Rate is "USDT per 1.0 Bond".
        // Example: Rate 1e6 (1 USDT) per 1e18 Bond.
        // Cost = 100e18 * 1e6 / 1e18 = 100e6. Correct.

        require(reserve >= totalCost, "Insufficient Reserve");

        reserve -= totalCost;
        cumulativeYieldPerToken += ratePerToken; // Rate must be scaled to 18 decimals for accumulating?
        // cumulativeYieldPerToken is used as: balance * (cum - paid) / 1e18.
        // Balance = 1e18. Result = 1e18 * Rate / 1e18 = Rate.
        // So Rate should be in PAYMENT TOKEN UNITS normalized?
        // If PaymentToken is 6 decimals. Rate is 6 decimals?
        // If Rate is 6 decimals (e.g. 1e6).
        // Result = 100e18 * 1e6 / 1e18 = 100e6. Correct.

        emit YieldDistributed(ratePerToken, totalCost);
    }

    /**
     * @notice Legacy support or Direct Distribution (Amount / Supply).
     */
    function depositYield(uint256 amount) external {
        paymentToken.safeTransferFrom(msg.sender, address(this), amount);

        uint256 supply = bond.totalSupply();
        require(supply > 0, "No bonds minted");

        // Rate = (Amount * 1e18) / Supply
        // If Amount 100e6. Supply 100e18.
        // Rate = 100e6 * 1e18 / 100e18 = 1e6.
        uint256 rate = (amount * 1e18) / supply;
        cumulativeYieldPerToken += rate;

        emit CouponDistributed(amount, rate);
    }

    /**
     * @notice User claims their share.
     */
    function claim() external updateReward(msg.sender) {
        uint256 reward = rewards[msg.sender];
        require(reward > 0, "Nothing to claim");

        rewards[msg.sender] = 0;

        paymentToken.safeTransfer(msg.sender, reward);

        emit CouponClaimed(msg.sender, reward);
    }

    /**
     * @notice Admin claims on behalf of a user (Gasless Claim).
     */
    function adminClaim(
        address beneficiary
    ) external onlyRole(DEFAULT_ADMIN_ROLE) updateReward(beneficiary) {
        uint256 reward = rewards[beneficiary];
        require(reward > 0, "Nothing to claim");

        rewards[beneficiary] = 0;

        paymentToken.safeTransfer(beneficiary, reward);

        emit CouponClaimed(beneficiary, reward);
    }

    // View function for UI
    function claimableYield(address user) external view returns (uint256) {
        uint256 current = rewards[user];
        uint256 pending = (bond.balanceOf(user) *
            (cumulativeYieldPerToken - userPaidPerToken[user])) / 1e18;
        return current + pending;
    }
}

contracts/CrossChainInvestmentGateway.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@layerzerolabs/lz-evm-oapp-v2/contracts/oapp/OApp.sol";
import "@layerzerolabs/lz-evm-oapp-v2/contracts/oapp/OAppSender.sol";
import "@layerzerolabs/lz-evm-oapp-v2/contracts/oapp/OAppReceiver.sol";

interface ITreasury {
    function buyFor(uint256 amount, address beneficiary) external;
}

/**
 * @title CrossChainInvestmentGateway
 * @notice Enables cross-chain USDT investments via LayerZero V2
 * @dev Deployed on both source chains (Ethereum, BSC, etc.) and destination (Mantle)
 */
contract CrossChainInvestmentGateway is OApp {
    using SafeERC20 for IERC20;

    IERC20 public usdt;
    address public treasury; // Only used on Mantle (destination)

    // Track pending investments for refunds
    mapping(bytes32 => PendingInvestment) public pendingInvestments;

    struct PendingInvestment {
        address investor;
        uint256 amount;
        uint32 srcEid;
        bool processed;
    }

    event CrossChainInvestmentSent(
        address indexed investor,
        uint256 amount,
        uint32 dstEid,
        bytes32 guid
    );

    event CrossChainInvestmentReceived(
        address indexed investor,
        uint256 amount,
        uint32 srcEid,
        bytes32 guid
    );

    event InvestmentFailed(bytes32 indexed guid, string reason);

    constructor(
        address _endpoint,
        address _usdt,
        address _treasury,
        address _owner
    ) OApp(_endpoint, _owner) Ownable(_owner) {
        usdt = IERC20(_usdt);
        treasury = _treasury;
    }

    /**
     * @notice Send USDT cross-chain for bond investment
     * @param amount Amount of USDT to invest (6 decimals)
     * @param dstEid Destination endpoint ID (Mantle Sepolia)
     * @param extraOptions LayerZero options for gas
     */
    function investCrossChain(
        uint256 amount,
        uint32 dstEid,
        bytes calldata extraOptions
    ) external payable returns (bytes32 guid) {
        require(amount > 0, "Amount must be > 0");

        // Pull USDT from user
        usdt.safeTransferFrom(msg.sender, address(this), amount);

        // Encode the message: investor address + amount
        bytes memory payload = abi.encode(msg.sender, amount);

        // Build message options
        bytes memory options = extraOptions.length > 0
            ? extraOptions
            : _buildDefaultOptions(dstEid);

        // Send via LayerZero
        MessagingReceipt memory receipt = _lzSend(
            dstEid,
            payload,
            options,
            MessagingFee(msg.value, 0),
            payable(msg.sender)
        );

        guid = receipt.guid;

        // Store pending investment
        pendingInvestments[guid] = PendingInvestment({
            investor: msg.sender,
            amount: amount,
            srcEid: dstEid,
            processed: false
        });

        emit CrossChainInvestmentSent(msg.sender, amount, dstEid, guid);

        return guid;
    }

    /**
     * @notice Receive cross-chain message and execute investment
     * @dev Called by LayerZero endpoint on destination chain
     */
    function _lzReceive(
        Origin calldata _origin,
        bytes32 _guid,
        bytes calldata _payload,
        address, // _executor
        bytes calldata // _extraData
    ) internal virtual override {
        (address investor, uint256 amount) = abi.decode(
            _payload,
            (address, uint256)
        );

        try this.executeInvestment(investor, amount, _origin.srcEid, _guid) {
            emit CrossChainInvestmentReceived(
                investor,
                amount,
                _origin.srcEid,
                _guid
            );
        } catch Error(string memory reason) {
            emit InvestmentFailed(_guid, reason);
            // On failure, tokens stay in contract for manual recovery
        }
    }

    /**
     * @notice Execute the actual investment on Mantle
     * @dev Separated for try-catch error handling
     */
    function executeInvestment(
        address investor,
        uint256 amount,
        uint32 srcEid,
        bytes32 guid
    ) external {
        require(msg.sender == address(this), "Only self");
        require(treasury != address(0), "Treasury not set");

        // Approve treasury to spend USDT
        usdt.approve(treasury, amount);

        // Execute investment
        ITreasury(treasury).buyFor(amount, investor);

        // Mark as processed
        if (pendingInvestments[guid].investor != address(0)) {
            pendingInvestments[guid].processed = true;
        }
    }

    /**
     * @notice Quote cross-chain investment fee
     */
    function quoteCrossChainFee(
        uint32 dstEid,
        uint256 amount,
        bytes calldata extraOptions
    ) external view returns (uint256 nativeFee, uint256 lzTokenFee) {
        bytes memory payload = abi.encode(msg.sender, amount);
        bytes memory options = extraOptions.length > 0
            ? extraOptions
            : _buildDefaultOptions(dstEid);

        MessagingFee memory fee = _quote(dstEid, payload, options, false);
        return (fee.nativeFee, fee.lzTokenFee);
    }

    /**
     * @notice Build default LayerZero options
     */
    function _buildDefaultOptions(
        uint32 dstEid
    ) internal pure returns (bytes memory) {
        // Gas limit for destination execution (adjust based on your needs)
        uint128 gasLimit = 200000;
        return abi.encodePacked(uint16(1), gasLimit);
    }

    /**
     * @notice Update treasury address (Mantle only)
     */
    function setTreasury(address _treasury) external onlyOwner {
        treasury = _treasury;
    }

    /**
     * @notice Rescue tokens in case of failed transfers
     */
    function rescueTokens(
        address token,
        uint256 amount,
        address to
    ) external onlyOwner {
        IERC20(token).safeTransfer(to, amount);
    }

    /**
     * @notice Withdraw native token (for LayerZero fees refund)
     */
    function withdrawNative(
        address payable to,
        uint256 amount
    ) external onlyOwner {
        (bool success, ) = to.call{value: amount}("");
        require(success, "Transfer failed");
    }

    receive() external payable {}
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title IdentityRegistry
 * @dev Maps Wallet Addresses to National Identities (Hashed).
 *      - Acts as the foundational "Digital Passport" system.
 *      - Only verified citizens can holding/trading Sovereign Bonds.
 */
contract IdentityRegistry is AccessControl {
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");

    // Wallet -> National ID Hash (e.g., keccak256("IND-123456789"))
    mapping(address => bytes32) public nationalIds;
    // Prevent duplicate registrations of the same ID to multiple wallets?
    // For simplicity, we allow 1:1 map. 
    mapping(bytes32 => address) public idToWallet;

    event IdentityVerified(address indexed wallet, bytes32 indexed nationalIdHash);
    event IdentityRevoked(address indexed wallet);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REGISTRAR_ROLE, admin);
    }

    /**
     * @notice Registers a citizen's wallet.
     * @param wallet The user's wallet address.
     * @param nationalIdHash Hash of the National ID (GDPR/Privacy safe).
     */
    function register(address wallet, bytes32 nationalIdHash) external onlyRole(REGISTRAR_ROLE) {
        require(nationalIds[wallet] == bytes32(0), "Already registered");
        require(idToWallet[nationalIdHash] == address(0), "ID already linked");
        
        nationalIds[wallet] = nationalIdHash;
        idToWallet[nationalIdHash] = wallet; // Bijective map

        emit IdentityVerified(wallet, nationalIdHash);
    }

    /**
     * @notice Revokes a user's status (e.g. lost keys, death).
     */
    function revoke(address wallet) external onlyRole(REGISTRAR_ROLE) {
        bytes32 id = nationalIds[wallet];
        delete nationalIds[wallet];
        delete idToWallet[id];
        
        emit IdentityRevoked(wallet);
    }

    /**
     * @notice Check if a wallet is verified.
     */
    function isVerified(address wallet) external view returns (bool) {
        return nationalIds[wallet] != bytes32(0);
    }
}

contracts/IdentityRegistryV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title IdentityRegistryV2
 * @notice Automated KYC registry with AI verification and wallet binding
 * @dev Stores only cryptographic proofs, never raw identity data
 */
contract IdentityRegistryV2 is AccessControl {
    bytes32 public constant KYC_VERIFIER_ROLE = keccak256("KYC_VERIFIER_ROLE");
    bytes32 public constant REVOKER_ROLE = keccak256("REVOKER_ROLE");

    struct IdentityProof {
        bytes32 kycHash;        // keccak256(aadhaarHash + walletSignature)
        uint256 verifiedAt;     // Timestamp of verification
        uint256 expiresAt;      // KYC expiry (365 days from verification)
        bool isRevoked;         // Admin revocation flag
        uint8 riskScore;        // 0-100 (AI fraud score, 0 = lowest risk)
    }

    // Wallet => Identity Proof
    mapping(address => IdentityProof) public identities;
    
    // Prevent duplicate Aadhaar usage
    mapping(bytes32 => address) public aadhaarHashToWallet;

    event IdentityVerified(
        address indexed wallet,
        bytes32 indexed kycHash,
        uint256 expiresAt,
        uint8 riskScore
    );
    
    event IdentityRevoked(address indexed wallet, string reason);
    event IdentityExpired(address indexed wallet);

    error AlreadyVerified(address wallet);
    error AadhaarAlreadyUsed(address existingWallet);
    error NotVerified(address wallet);

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(KYC_VERIFIER_ROLE, admin);
        _grantRole(REVOKER_ROLE, admin);
    }

    /**
     * @notice Register verified identity (called by AI backend)
     * @param wallet User's wallet address
     * @param aadhaarHash keccak256(aadhaarNumber)
     * @param walletSignature User's signature binding identity to wallet
     * @param riskScore AI-calculated fraud score (0-100)
     */
    function registerVerified(
        address wallet,
        bytes32 aadhaarHash,
        bytes memory walletSignature,
        uint8 riskScore
    ) external onlyRole(KYC_VERIFIER_ROLE) {
        // 1. Check if wallet already verified
        if (identities[wallet].verifiedAt != 0 && !identities[wallet].isRevoked) {
            revert AlreadyVerified(wallet);
        }

        // 2. Check if Aadhaar already linked to another wallet
        address existingWallet = aadhaarHashToWallet[aadhaarHash];
        if (existingWallet != address(0) && existingWallet != wallet) {
            revert AadhaarAlreadyUsed(existingWallet);
        }

        // 3. Generate KYC hash (Aadhaar + Signature binding)
        bytes32 kycHash = keccak256(abi.encodePacked(aadhaarHash, walletSignature));

        // 4. Store identity proof
        uint256 expiresAt = block.timestamp + 365 days;
        identities[wallet] = IdentityProof({
            kycHash: kycHash,
            verifiedAt: block.timestamp,
            expiresAt: expiresAt,
            isRevoked: false,
            riskScore: riskScore
        });

        aadhaarHashToWallet[aadhaarHash] = wallet;

        emit IdentityVerified(wallet, kycHash, expiresAt, riskScore);
    }

    /**
     * @notice Revoke identity (compliance/fraud action)
     */
    function revoke(address wallet, string calldata reason) 
        external 
        onlyRole(REVOKER_ROLE) 
    {
        if (identities[wallet].verifiedAt == 0) revert NotVerified(wallet);
        
        identities[wallet].isRevoked = true;
        emit IdentityRevoked(wallet, reason);
    }

    /**
     * @notice Check if wallet is verified and not expired/revoked
     */
    function isVerified(address wallet) external view returns (bool) {
        IdentityProof memory proof = identities[wallet];
        
        if (proof.verifiedAt == 0) return false;
        if (proof.isRevoked) return false;
        if (block.timestamp > proof.expiresAt) return false;
        
        return true;
    }

    /**
     * @notice Get identity details
     */
    function getIdentity(address wallet) 
        external 
        view 
        returns (
            bytes32 kycHash,
            uint256 verifiedAt,
            uint256 expiresAt,
            bool isRevoked,
            uint8 riskScore
        ) 
    {
        IdentityProof memory proof = identities[wallet];
        return (
            proof.kycHash,
            proof.verifiedAt,
            proof.expiresAt,
            proof.isRevoked,
            proof.riskScore
        );
    }
}

